head.script:
scwin.gDepCd = $c.stf.getUserInfo($p, "depCd");
scwin.gEmpNo = $c.stf.getUserInfo($p, "empNo");
scwin.gEmpNm = $c.stf.getUserInfo($p, "empNm");
scwin.gLdMktTp = $c.stf.getUserInfo($p, "market");
scwin.gUsrTpCd = $c.stf.getUserInfo($p, "usrTpCd");
scwin.vScrenID = "ULDSTF30403.xml";
// 전역 변수 선언
scwin.gLastJob = "";
scwin.vCONTN_ID = "";

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function () {
    // 영문공시제출 오픈시 아래 부분 삭제
    //--------------------------------------------------
    grp_eng_comment.hide();
    grp_eng_fil.hide();
    //----------------------------------------------------
    scwin.setMenuflag();
    sbx_MENU_FLAG.setValue("");

    scwin.initPage();
    scwin.setKclicStatus('init');
};

scwin.onpageunload = function () {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.btn_AddRow_onclick = function (e) {
    // 공시발간자료 일 경우에만 파일첨부 6개까지 허용 가능토록 수정 by LDJ_20130219
    if (sbx_MENU_FLAG.getValue() === "04") {
        if (dlt_FILE_LIST.getRowCount() === 6) {
            $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
    } else {
        if (dlt_FILE_LIST.getRowCount() === 5) {
            $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
    }
};

scwin.btn_DelRow_onclick = function (e) {
    const idxArrJson = grd_FILE_LIST.getCheckedJSON("chk");
    const idxArrIndex = grd_FILE_LIST.getCheckedIndex("chk");
    for (let i = 0; i < idxArrJson.length; i++) {
        const fileName = idxArrJson[i].attachFileNm;
        mpd_file.removeFile(fileName);
    }
    dlt_FILE_LIST.removeRows(idxArrIndex);
};

scwin.btn_Save_onclick = function (e) {
    scwin.save();
};

scwin.btn_Delete_onclick = function (e) {
    scwin.delete();
};

scwin.btn_Cancel_onclick = function (e) {
    $c.win.closePopup();
};

scwin.grd_FILE_LIST_oncellclick = function (rowIndex, columnIndex, columnId) {
    scwin.downLoad(rowIndex, columnId);
};

scwin.sbx_MENU_FLAG_onviewchange = function (info) {
    const gValueUp = sbx_MENU_FLAG.getValue();
    if (gValueUp === '62') {
        //밸류업자료실(국문)
        rdo_mkt_gubun.setValue("9");
        rdo_mkt_gubun.setDisabled(true);
        if (cbx_OBJ_SYSTEM2.getValue() === "Y" &&
            cbx_OBJ_SYSTEM1.getValue() === "N" &&
            cbx_OBJ_SYSTEM3.getValue() === "N" &&
            cbx_OBJ_SYSTEM4.getValue() === "N" &&
            cbx_OBJ_SYSTEM5.getValue() === "N") {

        } else {
            $c.win.alert("[밸류업 자료실(국문)]은 조회(국문)시스템만 적용됩니다. <br>공지대상시스템을 [조회(국문)]만 선택해주세요.");
        }
    } else if (gValueUp === '63') {
        //밸류업자료실(영문)
        if (cbx_OBJ_SYSTEM2.getValue() === "N" &&
            cbx_OBJ_SYSTEM1.getValue() === "N" &&
            cbx_OBJ_SYSTEM3.getValue() === "N" &&
            cbx_OBJ_SYSTEM4.getValue() === "N" &&
            cbx_OBJ_SYSTEM5.getValue() === "Y") {

        } else {
            $c.win.alert("[밸류업 자료실(영문)]은 조회(영문)시스템만 적용됩니다. <br>공지대상시스템을 [조회(영문)]만 선택해주세요.");
        }
    } else {
        rdo_mkt_gubun.setDisabled(false);
    }

    // 공시발간자료 일 경우에만 파일첨부 6개까지 허용 가능토록 수정 by LDJ_20130219
    // if (sbx_MENU_FLAG.getValue() == "04") {
    //     if (dlt_FILE_LIST.getTotalRow() == 6) {
    //         $c.win.alert("더이상 추가하실 수 없습니다.");
    //         return;
    //     }
    // } else {
    //     if (dlt_FILE_LIST.getTotalRow() == 5) {
    //         $c.win.alert("더이상 추가하실 수 없습니다.");
    //         return;
    //     }
    // }

    if (gValueUp === "04") {
        mpd_file.setMaxFileCount(6);
    } else {
        mpd_file.setMaxFileCount(5);
    }
};

scwin.cbx_OBJ_SYSTEM1_onviewchange = function (info) {
    //제출(국문)
    if (cbx_OBJ_SYSTEM1.getValue() === true) {
        sbx_MENU_FLAG.setDisabled(false);
        if (cbx_OBJ_SYSTEM4.getValue() === "N") {
            sbx_sprt_room_grp.setDisabled(true);
            sbx_chrg_inst_id.setDisabled(true);
            sbx_sprt_room_grp.setValue("");
            sbx_chrg_inst_id.setValue("");
        }
    }

    if (cbx_OBJ_SYSTEM5.getValue() === "N" && cbx_OBJ_SYSTEM4.getValue() === "N" && cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
        sbx_sprt_room_grp.setDisabled(false);
        sbx_chrg_inst_id.setDisabled(false);
        sbx_MENU_FLAG.setDisabled(false);
        rdo_mkt_gubun.setDisabled(false);
    }

    scwin.setKclicStatus();
};

scwin.cbx_OBJ_SYSTEM2_onviewchange = function (info) {
    //조회(국문)
    if (cbx_OBJ_SYSTEM2.getValue() === true) {
        sbx_MENU_FLAG.setDisabled(false);
        if (cbx_OBJ_SYSTEM4.getValue() === "N") {
            sbx_sprt_room_grp.setDisabled(true);
            sbx_chrg_inst_id.setDisabled(true);
            sbx_sprt_room_grp.setValue("");
            sbx_chrg_inst_id.setValue("");
        }
    }

    if (cbx_OBJ_SYSTEM5.getValue() === "N" && cbx_OBJ_SYSTEM4.getValue() === "N" && cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
        sbx_sprt_room_grp.setDisabled(false);
        sbx_chrg_inst_id.setDisabled(false);
        sbx_MENU_FLAG.setDisabled(false);
        rdo_mkt_gubun.setDisabled(false);
    }

    scwin.setKclicStatus();
};

scwin.cbx_OBJ_SYSTEM4_onviewchange = function (info) {
    //K-CLIC
    scwin.setKclicStatus();
};

scwin.cbx_OBJ_SYSTEM5_onviewchange = function (info) {
    //조회(영문)
    if (cbx_OBJ_SYSTEM5.getValue() === true) {
        scwin.setMenuflag("eng");
        sbx_MENU_FLAG.setValue("63");
        sbx_MENU_FLAG.setDisabled(true);
        rdo_mkt_gubun.setValue("9");
        rdo_mkt_gubun.setDisabled(true);
        sbx_sprt_room_grp.setDisabled(true);
        sbx_chrg_inst_id.setDisabled(true);
        sbx_sprt_room_grp.setValue("");
        sbx_chrg_inst_id.setValue("");

        if (cbx_OBJ_SYSTEM4.getValue() === true || cbx_OBJ_SYSTEM3.getValue() === true ||
            cbx_OBJ_SYSTEM2.getValue() === true || cbx_OBJ_SYSTEM1.getValue() === true) {
            $c.win.alert("조회(영문) 시스템은 다른 시스템과 같이 사용할 수 없습니다.");
        }

        cbx_OBJ_SYSTEM4.setValue("N");
        cbx_OBJ_SYSTEM4.setDisabled(true);
        cbx_OBJ_SYSTEM3.setValue("N");
        cbx_OBJ_SYSTEM3.setDisabled(true);
        cbx_OBJ_SYSTEM2.setValue("N");
        cbx_OBJ_SYSTEM2.setDisabled(true);
        cbx_OBJ_SYSTEM1.setValue("N");
        cbx_OBJ_SYSTEM1.setDisabled(true);
    } else {
        scwin.setMenuflag("ko");
        sbx_MENU_FLAG.setValue("");
        sbx_MENU_FLAG.setDisabled(false);
    }

    if (cbx_OBJ_SYSTEM5.getValue() === "N" && cbx_OBJ_SYSTEM4.getValue() === "N" && cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
        sbx_sprt_room_grp.setDisabled(false);
        sbx_chrg_inst_id.setDisabled(false);
        sbx_MENU_FLAG.setDisabled(false);
        rdo_mkt_gubun.setDisabled(false);
        cbx_OBJ_SYSTEM4.setDisabled(false);
        cbx_OBJ_SYSTEM3.setDisabled(false);
        cbx_OBJ_SYSTEM2.setDisabled(false);
        cbx_OBJ_SYSTEM1.setDisabled(false);
    }
};

// 일반 함수
scwin.initPage = function () {
    if ($p.getPopupId().includes("INTEBBS_NEW")) {
        // gfm은 정적인 화면이라 변수값을 받을 수 없어. 창의 이름으로 신규와 수정을 구별한다. 
        ibx_WRTR_EMP_NO.setValue(scwin.gEmpNo);
        ibx_WRTR_EMP_NM.setValue(scwin.gEmpNm);
        btn_Delete.hide();
    } else {
        scwin.vCONTN_ID = $c.data.getParameter("contnId");
        scwin.setEditMode();
    }
};

scwin.setMenuflag = function (gubun) {
    dlt_MENU_FLAG.setJSON([]);
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(0, "code", "04");
    dlt_MENU_FLAG.setCellData(0, "codeNm", "공시발간자료");
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(1, "code", "02");
    dlt_MENU_FLAG.setCellData(1, "codeNm", "자료실");
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(2, "code", "31");
    dlt_MENU_FLAG.setCellData(2, "codeNm", "공시체크포인트");
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(3, "code", "32");
    dlt_MENU_FLAG.setCellData(3, "codeNm", "업무사례");
    dlt_MENU_FLAG.insertRow();
    dlt_MENU_FLAG.setCellData(4, "code", "62");
    dlt_MENU_FLAG.setCellData(4, "codeNm", "밸류업자료실(국문)");

    if (gubun === "eng") {
        dlt_MENU_FLAG.insertRow();
        dlt_MENU_FLAG.setCellData(5, "code", "63");
        dlt_MENU_FLAG.setCellData(5, "codeNm", "밸류업자료실(영문)");
    }
};

scwin.setEditMode = async function () {
    let url = "/IntegratedBBS.do?method=readDsclBbs";
    url += "&CONTN_ID=" + scwin.vCONTN_ID;

    $c.sbm.setAction(sbm_MASTER, url);
    let ret = await $c.sbm.execute(sbm_MASTER);

    url = "/IntegratedBBS.do?method=listInteBBSAttach";
    url += "&CONTN_ID=" + scwin.vCONTN_ID;

    $c.sbm.setAction(sbm_FILE_LIST, url);
    ret = await $c.sbm.execute(sbm_FILE_LIST);
};

scwin.checkForm = function () {
    if (ibx_WRTR_EMP_NM.getValue() === "") {
        $c.win.alert("[등록자]를 입력하세요.");
        return false;
    }
    if (ibx_WRTR_EMP_NM.getValue().length > 10) {
        $c.win.alert("[등록자]명을 10자 이내로 입력해 주세요.");
        ibx_WRTR_EMP_NM.focus();
        return false;
    }
    if (cbx_OBJ_SYSTEM1.getValue() === "N" &&
        cbx_OBJ_SYSTEM2.getValue() === "N" &&
        cbx_OBJ_SYSTEM3.getValue() === "N" &&
        cbx_OBJ_SYSTEM4.getValue() === "N" &&
        cbx_OBJ_SYSTEM5.getValue() === "N") {
        $c.win.alert("[공지대상시스템]를 선택하세요.");
        return false;
    }
    if (ibx_WRTR_EMAIL.getValue() === "") {
        $c.win.alert("[이메일]를 입력하세요.");
        ibx_WRTR_EMAIL.focus();
        return false;
    }
    if ($c.stf.IsValidEmail(ibx_WRTR_EMAIL.getValue()) === false) {
        $c.win.alert("[이메일] 정확하지 않습니다.");
        ibx_WRTR_EMAIL.focus();
        return false;
    }
    if (ibx_PW.getValue() === "") {
        $c.win.alert("[비밀번호]를 입력하세요.");
        //ibx_PW.focus();
        return false;
    }
    if (ibx_TITLE.getValue() === "") {
        $c.win.alert("[제목]를 입력하세요.");
        ibx_TITLE.focus();
        return false;
    }
    if (sbx_MENU_FLAG.getValue() === "" && cbx_OBJ_SYSTEM4.getValue() !== true) {
        $c.win.alert("[메뉴구분]를 선택하세요.");
        sbx_MENU_FLAG.focus();
        return false;
    }
    if (rdo_mkt_gubun.getValue() === "") {
        $c.win.alert("[시장구분]를 선택하세요.");
        rdo_mkt_gubun.focus();
        return false;
    }
    if (txa_CONTN_CONTN.getValue() === "") {
        $c.win.alert("[내용]를 입력하세요.");
        txa_CONTN_CONTN.focus();
        return false;
    }

    if (sbx_MENU_FLAG.getValue() === "31" || sbx_MENU_FLAG.getValue() === "32") {
        if (sbx_MENU_FLAG.getValue() === "31" && (cbx_OBJ_SYSTEM1.getValue() === "N" || (cbx_OBJ_SYSTEM1.getValue() === "Y" && cbx_OBJ_SYSTEM2.getValue() === "Y"))) {
            $c.win.alert("[공시체크포인트]는 제출시스템에만 적용됩니다.<br>공지대상시스템을 [제출]로 선택하여주세요.");
            return false;
        }
        if (sbx_MENU_FLAG.getValue() === "32" && (cbx_OBJ_SYSTEM1.getValue() === "N" || (cbx_OBJ_SYSTEM1.getValue() === "Y" && cbx_OBJ_SYSTEM2.getValue() === "Y"))) {
            $c.win.alert("[업무사례]는 제출시스템에만 적용됩니다.<br>공지대상시스템을 [제출]로 선택하여주세요.");
            return false;
        }
        if (sbx_MENU_FLAG.getValue() === "31" && rdo_mkt_gubun.getValue() === "4") {
            $c.win.alert("[공시체크포인트]은 시장구분[채권]에 적용할 수 없습니다.");
            return false;
        }
        if (sbx_MENU_FLAG.getValue() === "32" && rdo_mkt_gubun.getValue() === "4") {
            $c.win.alert("[업무사례]는 시장구분[채권]에 적용할 수 없습니다.");
            return false;
        }
    }
    //202405 밸류업 추가 
    if (sbx_MENU_FLAG.getValue() === "62") {
        if (cbx_OBJ_SYSTEM2.getValue() === "Y" &&
            cbx_OBJ_SYSTEM1.getValue() === "N" &&
            cbx_OBJ_SYSTEM3.getValue() === "N" &&
            cbx_OBJ_SYSTEM4.getValue() === "N" &&
            cbx_OBJ_SYSTEM5.getValue() === "N") {

        } else {
            $c.win.alert("[밸류업 자료실(국문)]은 조회(국문)시스템만 적용됩니다. <br>공지대상시스템을 [조회(국문)]만 선택하여주세요.");
            return false;
        }
    }
    if (sbx_MENU_FLAG.getValue() === "63") {
        if (cbx_OBJ_SYSTEM2.getValue() === "N" &&
            cbx_OBJ_SYSTEM1.getValue() === "N" &&
            cbx_OBJ_SYSTEM3.getValue() === "N" &&
            cbx_OBJ_SYSTEM4.getValue() === "N" &&
            cbx_OBJ_SYSTEM5.getValue() === "Y") {

        } else {
            $c.win.alert("[밸류업 자료실(영문)]은 조회(영문)시스템만 적용됩니다. <br>공지대상시스템을 [조회(영문)]만 선택하여주세요.");
            return false;
        }
    }
    if (cbx_OBJ_SYSTEM4.getValue() === "Y") {
        //K-CLIC 
        if (sbx_sprt_room_grp.getValue() === "") {
            $c.win.alert("공지대상시스템이 K-CLIC인 경우에는 게시물유형을 선택해 주세요.");
            sbx_sprt_room_grp.focus();
            return false;
        }
        if (sbx_chrg_inst_id.getValue() === "") {
            $c.win.alert("공지대상시스템이 K-CLIC인 경우에는 담당기관을 선택해 주세요.");
            sbx_chrg_inst_id.focus();
            return false;
        }
    }

    //날짜확인
    if (!$c.stf.compareFromToDate2(ica_SDate, ica_EDate)) {
        ica_SDate.focus();
        return false;
    }

    return true;
};

scwin.save = async function () {
    if (scwin.checkForm() === false) return;

    let res = await $c.win.confirm("[저장]하시겠습니까?");
    if (res) {
        scwin.gLastJob = "저장";
        let url = "/IntegratedBBS.do?method=registerDsclBbs" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        // TODO Stage2: trs action 확인 - 원본 KeyValue "JSP(I:pInputMaster=dlt_MASTER, I:pFile=dlt_FILE_LIST)" 의 ref 매핑 검증
        const sbmOptions = {
            id : "sbm_Save",
            action : url,
            ref : "dma_MASTER",
            submitDoneHandler : scwin.sbm_Save_submitdone,
            isProcessMsg : false
        };
        $c.sbm.executeDynamic(sbmOptions);
        //--------------------------------------------------

        mpd_file.changeAction("http://localhost/api/discls/dsclinfo/insert-notice-content");	//action 설정

        let param = { "wrtrEmail": "eds@krx.co.kr", "notiEndDd": "20261224", "pw": "1234", "notiObjSysTpCd": "1,2,3,B", "wrtrEmpNm": "시스템관리자", "bbsTpCd": "03", "mktTpCd": "1", "title": "공지사항 - 제출", "contnMaindocContn": "string", "notiStrtDd": "20260601", "chrgInstId": "KRX" };
        mpd_file.setParam(0, "data", JSON.stringify(param));	//data param 설정
        mpd_file.startUpload();
    }
};

scwin.delete = async function () {
    const vPW = ibx_PW.getValue();
    if (vPW === "") {
        $c.win.alert("[비밀번호]를 입력하세요.");
        //ibx_PW.focus();
        return;
    }

    let res = await $c.win.confirm("[삭제]하시겠습니까?");
    if (res) {
        scwin.gLastJob = "삭제";
        let url = "/IntegratedBBS.do?method=removeDsclBbs" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        // TODO Stage2: trs action 확인 - 원본 KeyValue "JSP(I:pInputMaster=dlt_MASTER)" 의 ref 매핑 검증
        const sbmOptions = {
            id : "sbm_Save",
            action : url,
            ref : "dma_MASTER",
            submitDoneHandler : scwin.sbm_Save_submitdone,
            isProcessMsg : false
        };
        $c.sbm.executeDynamic(sbmOptions);
    }
};

scwin.downLoad = function (row, colid) {
    let filename = dlt_FILE_LIST.getCellData(row, "attachFileNm");

    if (filename === "") return;

    if (colid === "attachFileNm") {
        let contnId = dlt_FILE_LIST.getCellData(row, "contnId");
        let contnAttachSeq = dlt_FILE_LIST.getCellData(row, "contnAttachSeq");
        let url = "/api/discls/common/file/download";
        url += "?gubun=2&contnId=" + contnId + "&contnAttachSeq=" + contnAttachSeq;

        $p.download(url, {}, "get", true);
    }
};

scwin.setKclicStatus = function (status) {
    if (cbx_OBJ_SYSTEM4.getValue() === true) {
        sbx_sprt_room_grp.setDisabled(false);
        sbx_chrg_inst_id.setDisabled(false);
        if (cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
            if ('init' !== status) {
                sbx_MENU_FLAG.setValue("02");
            }
            sbx_MENU_FLAG.setDisabled(true);
        }
    } else if (cbx_OBJ_SYSTEM5.getValue() === true) {
        scwin.setMenuflag("eng");
        sbx_MENU_FLAG.setValue("63");
        sbx_MENU_FLAG.setDisabled(true);
        rdo_mkt_gubun.setValue("9");
        rdo_mkt_gubun.setDisabled(true);
        sbx_sprt_room_grp.setDisabled(true);
        sbx_chrg_inst_id.setDisabled(true);
        sbx_sprt_room_grp.setValue("");
        sbx_chrg_inst_id.setValue("");
        cbx_OBJ_SYSTEM4.setValue("N");
        cbx_OBJ_SYSTEM4.setDisabled(false);
        cbx_OBJ_SYSTEM3.setValue("N");
        cbx_OBJ_SYSTEM3.setDisabled(false);
        cbx_OBJ_SYSTEM2.setValue("N");
        cbx_OBJ_SYSTEM2.setDisabled(false);
        cbx_OBJ_SYSTEM1.setValue("N");
        cbx_OBJ_SYSTEM1.setDisabled(false);
    } else {
        sbx_sprt_room_grp.setDisabled(true);
        sbx_chrg_inst_id.setDisabled(true);
        sbx_sprt_room_grp.setValue("");
        sbx_chrg_inst_id.setValue("");
        sbx_MENU_FLAG.setDisabled(false);
    }

    if (cbx_OBJ_SYSTEM5.getValue() === "N" && cbx_OBJ_SYSTEM4.getValue() === "N" && cbx_OBJ_SYSTEM2.getValue() === "N" && cbx_OBJ_SYSTEM1.getValue() === "N") {
        sbx_sprt_room_grp.setDisabled(false);
        sbx_chrg_inst_id.setDisabled(false);
        sbx_MENU_FLAG.setDisabled(false);
        rdo_mkt_gubun.setDisabled(false);
    }
};

//2017-02-13 KBoY FileSizeLimit 30MB		
scwin.canUploadFile = function (size) {
    const maxFileSize = 1024 * 1024 * 30; //30MB		
    if (size < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

//20250718 파일 확장자 체크로직 추가
scwin.checkExtension = function (fileNm) {
    const fileExts = new Array(".hwp", ".docx", ".doc", ".xls", ".xlsx", ".ppt", ".pptx", ".pdf", ".gif", ".jpg", ".jpeg", ".bmp", ".tif", ".txt", ".drt", ".dsd", ".png", ".zip"); // 허가 확장자 목록
    const vsFileNm = fileNm;
    const vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    let vsFlag = true;
    const ext = fileNm.substr(fileNm.lastIndexOf(".")).toLowerCase();
    for (let i = 0; i < fileExts.length; i++) {
        if (fileExts[i] === vsFileExts || fileExts[i] === ext) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};

scwin.checkMaxLength1 = function (filestr, size, lbl) {
    const overLen = $c.stf.getStringSize(filestr) - size;
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 의 최대길이는 [ " + size + " ] byte 입니다.    <br>[ " + overLen + " ] byte 를 초과하였습니다.<br>확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return true;
    }
    return false;
};

//파일업로드시 파일정보 dataList에 세팅
scwin.selectCallback = function () {
    const fileInfos = mpd_file.getFileInfos();
    // dlt_FILE_LIST.setJSON(fileInfos);

    for (let i = 0; i < fileInfos.length; i++) {
        let vFileNm = fileInfos[i].name;
        let vSize = fileInfos[i].size;

        if (vFileNm !== "") {
            //파일 확장자 체크 추가
            if (scwin.checkMaxLength1(vFileNm, '80', "파일명")) return; //파일명 80자 체크
            if (scwin.checkExtension(vFileNm)) return; // 파일 확장자 체크

            if (!scwin.canUploadFile(vSize)) {
                $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
                return;
            } else {
                let newRow = dlt_FILE_LIST.insertRow();
                dlt_FILE_LIST.setCellData(newRow, "attachFileNm", returnArr[i]);
            }
        } else {
            return;
        }
    }    
};

scwin.sbm_Save_submitdone = async function (e) {
    if (!e.responseJSON.success) {
        return;
    }

    const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    $p.parent().scwin.fn_listDsclBbs();
    $c.win.closePopup();
};
